import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Plan — FR 3.2.8: Logout","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-8-logout/plan.md","filePath":"feature/srs/01-authentication/3-2-8-logout/plan.md"}'),r={name:"feature/srs/01-authentication/3-2-8-logout/plan.md"};function s(i,e,c,n,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-8-logout" tabindex="-1">Plan — FR 3.2.8: Logout <a class="header-anchor" href="#plan-—-fr-3-2-8-logout" aria-label="Permalink to &quot;Plan — FR 3.2.8: Logout&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Current-device session termination (<code>POST /api/v1/auth/logout</code>), Redis JWT access/refresh token blacklisting (<code>BR-05</code>), <code>HttpOnly</code> cookie clearing, IP/User-Agent audit logging, and client-side <code>lastUsedLoginMethod</code> persistence.</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>JwtAuthFilterGatewayFilterFactory.java</code> (checks Redis <code>jwt:blacklist:{jti}</code> on every subsequent request)</td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/AuthController.java</code> (<code>logout</code> extracting <code>Authorization</code> header, <code>refreshToken</code> cookie, <code>X-Forwarded-For</code>, and <code>User-Agent</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/AuthServiceImpl.java</code> (<code>logout</code>), <code>util/JwtUtil.java</code> (<code>blacklistToken</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>AuditLogRepository.java</code> (<code>AuditLog</code> with <code>ip_address</code> &amp; <code>user_agent</code>), <code>UserRefreshTokenRepository.java</code>, Redis <code>jwt:blacklist:{jti}</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/components/layout/{Navbar,Sidebar}.tsx</code>, <code>src/services/authService.ts</code>, <code>src/stores/authStore.ts</code>, <code>src/pages/auth/LoginPage.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>src/screens/settings/SettingsScreen.tsx</code>, <code>src/utils/confirmSignOut.ts</code>, <code>src/services/authService.ts</code>, <code>src/store/authStore.ts</code></td></tr></tbody></table><h2 id="_2-database-redis-localstorage-design" tabindex="-1">2. Database, Redis &amp; LocalStorage Design <a class="header-anchor" href="#_2-database-redis-localstorage-design" aria-label="Permalink to &quot;2. Database, Redis &amp; LocalStorage Design&quot;">​</a></h2><ul><li><strong>Redis Token Blacklist:</strong> <code>jwt:blacklist:{jti}</code> set with TTL equal to the remaining lifetime of the presented <code>accessToken</code> and <code>refreshToken</code> so neither token can be replayed at <code>brandhub-api-gateway</code> or <code>/api/v1/auth/refresh</code>.</li><li><strong>PostgreSQL <code>user_refresh_tokens</code> &amp; <code>audit_logs</code>:</strong><ul><li>Marks only the current device&#39;s refresh token revoked (leaving other signed-in devices active).</li><li>Inserts <code>AuditLog(userId, action=LOGOUT, resourceType=&quot;USER&quot;, ipAddress, userAgent)</code> (<code>2026-09-23-audit-log-ip-user-agent.sql</code>: <code>ip_address VARCHAR(45)</code>, <code>user_agent VARCHAR(512)</code>).</li></ul></li><li><strong>Client Storage (<code>lastUsedLoginMethod</code>):</strong><ul><li>Stored in browser <code>localStorage</code> / mobile preferences (<code>&quot;email&quot;</code> | <code>&quot;google_oauth&quot;</code>) during login and preserved across <code>clearAuth()</code> so <code>/login</code> highlights the user&#39;s last-used sign-in option without extra backend state.</li></ul></li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Client Sign-Out Trigger:</strong> User clicks Logout in <code>Navbar</code> / <code>Sidebar</code> (Web) or confirms sign-out via <code>confirmSignOut.ts</code> (Mobile).</li><li><strong>Backend Revocation (<code>POST /api/v1/auth/logout</code>):</strong><ul><li>Validates <code>Authorization: Bearer &lt;token&gt;</code> header presence (<code>401 INVALID_CREDENTIALS</code> if missing/malformed).</li><li>Parses <code>userId</code> and <code>jti</code> (gracefully handling already-expired tokens idempotently -&gt; still returns <code>200 OK</code>).</li><li>Blacklists <code>accessToken</code> and <code>refreshToken</code> <code>jti</code>s in Redis (<code>jwt:blacklist:{jti}</code>) for their remaining TTL, revokes matching <code>UserRefreshToken</code>, writes <code>AuditLog(LOGOUT, ipAddress, userAgent)</code>, and sets <code>Set-Cookie: refreshToken=; Max-Age=0; HttpOnly</code>.</li></ul></li><li><strong>Client State Cleanup:</strong> Clears <code>authStore</code> access token/user profile, clears TanStack Query user-scoped caches (preventing cross-account data flash), retains <code>lastUsedLoginMethod</code>, and redirects to <code>/login</code>.</li></ol><h2 id="_4-security-multi-device-isolation" tabindex="-1">4. Security &amp; Multi-Device Isolation <a class="header-anchor" href="#_4-security-multi-device-isolation" aria-label="Permalink to &quot;4. Security &amp; Multi-Device Isolation&quot;">​</a></h2><ul><li><strong>Per-Device Scope:</strong> Only the refresh token presented by the current browser/device is revoked; active sessions on other devices remain valid unless explicitly revoked via <code>POST /api/v1/auth/sessions/revoke-others</code>.</li><li><strong>Idempotent Expiry Resilience:</strong> Calling <code>/logout</code> with an already-expired JWT still clears cookies and returns <code>200 OK</code> so client sign-out never gets stuck in an error loop.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.8</code> — Logout</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/logout</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl, JwtUtil</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">Redis <code>jwt:blacklist:{jti}</code>; PostgreSQL <code>user_refresh_tokens</code>, <code>audit_logs</code> (<code>ip_address</code>, <code>user_agent</code>)</td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-05</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>401 INVALID_CREDENTIALS</code> (missing header); idempotent <code>200 OK</code> on expired token</td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/components/layout/Navbar.tsx</code>, <code>src/components/layout/Sidebar.tsx</code>, <code>src/services/authService.ts</code>, <code>src/stores/authStore.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>src/screens/settings/SettingsScreen.tsx</code>, <code>src/utils/confirmSignOut.ts</code>, <code>src/store/authStore.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>auth.logout.* / common.logout</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',15)])])}const p=t(r,[["render",s]]);export{h as __pageData,p as default};
